using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker(reorderThreshold: 5);
    }

    // --- Stock Level Tests ---

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-999"));
    }

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-1", 20);
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.AddStock("SKU-1", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", -5));
    }

    [TestMethod]
    public void AddStock_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(null!, 10));
    }

    [TestMethod]
    public void GetStockLevel_EmptySku_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(""));
    }

    // --- Remove Stock Tests ---

    [TestMethod]
    public void RemoveStock_SufficientStock_DecreasesLevel()
    {
        _tracker.AddStock("SKU-1", 20);
        _tracker.RemoveStock("SKU-1", 8);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_EntireStock_LeavesZero()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.RemoveStock("SKU-1", 10);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 5));
    }

    [TestMethod]
    public void RemoveStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-1", 0));
    }

    // --- Reorder Alert Tests ---

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-1", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-1", 6);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("SKU-UNKNOWN"));
    }

    // --- Warehouse Transfer Tests ---

    [TestMethod]
    public void TransferTo_ValidTransfer_MovesStockBetweenTrackers()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 20);

        _tracker.TransferTo(destination, "SKU-1", 7);

        Assert.AreEqual(13, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(7, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferTo_InsufficientStock_Throws()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 5);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferTo(destination, "SKU-1", 10));
    }

    [TestMethod]
    public void TransferTo_InsufficientStock_DoesNotModifyDestination()
    {
        var destination = new InventoryTracker();
        destination.AddStock("SKU-1", 2);
        _tracker.AddStock("SKU-1", 5);

        try { _tracker.TransferTo(destination, "SKU-1", 10); } catch { }

        Assert.AreEqual(2, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferTo_NullDestination_Throws()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferTo(null!, "SKU-1", 5));
    }

    [TestMethod]
    public void TransferTo_EntireStock_LeavesSourceAtZero()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 15);

        _tracker.TransferTo(destination, "SKU-1", 15);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(15, destination.GetStockLevel("SKU-1"));
    }

    // --- Constructor Tests ---

    [TestMethod]
    public void Constructor_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => new InventoryTracker(reorderThreshold: -1));
    }

    [TestMethod]
    public void Constructor_ZeroThreshold_IsValid()
    {
        var tracker = new InventoryTracker(reorderThreshold: 0);
        tracker.AddStock("SKU-1", 1);
        Assert.IsFalse(tracker.NeedsReorder("SKU-1"));
    }
}

